contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 newVal) public {
        uint256 minBefore = c.MinSum(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.SetMinSum(newVal); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint256 minAfter = c.MinSum(); if (__ESBMC_reverted()) return;
        assert(!reverted ? minAfter == newVal : minAfter == minBefore);
    }
}

